macro_rules! deps {
    () => {
        Side!();
        Hunk!();
    };
}

macro_rules! zealously_contract_hunks {
    () => {
        deps!();
        # [doc = " Reduce the area of `a_hunks` and the hunks in `b_hunks` so that only those lines that are"] # [doc = " actually different remain. Note that we have to compare the resolved values, not only the tokens,"] # [doc = " so `current_tokens` is expected to be known to the `input` (and its `interner`)."] # [doc = " Hunks from all input arrays maybe removed in the process from the front and back, in case they"] # [doc = " are entirely equal to each other."] # [doc = " Note also that `a_hunks` and `b_hunks` are treated to be consecutive, so [`fill_ancestor()`] must"] # [doc = " have been called beforehand, and are assumed to cover the same space in the ancestor buffer."] # [doc = ""] # [doc = " Return a new vector of all the hunks that were removed from front and back, with partial hunks inserted,"] # [doc = " along with the amount of hunks that go front, with the remaining going towards the back."] # [must_use] pub fn zealously_contract_hunks (a_hunks : & mut Vec < Hunk > , b_hunks : & mut Vec < Hunk > , input : & InternedInput < & [u8] > , current_tokens : & [Token] ,) -> (Vec < Hunk > , usize) { let line_content = | token_idx : u32 , side : Side | { let tokens = match side { Side :: Current => current_tokens , Side :: Other => & input . after , Side :: Ancestor => & input . before , } ; & input . interner [tokens [token_idx as usize]] } ; let (mut last_a_hunk_idx , mut last_b_hunk_idx) = (0 , 0) ; let (mut out , hunks_in_front) = { let (mut remove_leading_a_hunks_from , mut remove_leading_b_hunks_from) = (None , None) ; let (mut a_hunk_token_equal_till , mut b_hunk_token_equal_till) = (None , None) ; for ((a_token_idx , a_hunk_idx , a_hunk_side) , (b_token_idx , b_hunk_idx , b_hunk_side)) in iterate_hunks (a_hunks) . zip (iterate_hunks (b_hunks)) { let a_line = line_content (a_token_idx , a_hunk_side) . as_bstr () ; let b_line = line_content (b_token_idx , b_hunk_side) . as_bstr () ; if last_a_hunk_idx != a_hunk_idx { a_hunk_token_equal_till = None ; last_a_hunk_idx = a_hunk_idx ; } if last_b_hunk_idx != b_hunk_idx { b_hunk_token_equal_till = None ; last_b_hunk_idx = b_hunk_idx ; } if a_line == b_line { (remove_leading_a_hunks_from , remove_leading_b_hunks_from) = (Some (a_hunk_idx) , Some (b_hunk_idx)) ; (a_hunk_token_equal_till , b_hunk_token_equal_till) = (Some (a_token_idx) , Some (b_token_idx)) ; } else { break ; } } let mut out = Vec :: with_capacity (remove_leading_a_hunks_from . unwrap_or_else (| | { if a_hunk_token_equal_till . is_some () { 1 } else { 0 } })) ; truncate_hunks_from_from_front (a_hunks , remove_leading_a_hunks_from , a_hunk_token_equal_till , Some (& mut out) ,) ; truncate_hunks_from_from_front (b_hunks , remove_leading_b_hunks_from , b_hunk_token_equal_till , None) ; let hunks_in_front = out . len () ; (out , hunks_in_front) } ; (last_a_hunk_idx , last_b_hunk_idx) = (0 , 0) ; { let (mut remove_trailing_a_hunks_from , mut remove_trailing_b_hunks_from) = (None , None) ; let (mut a_hunk_token_equal_from , mut b_hunk_token_equal_from) = (None , None) ; for ((a_token_idx , a_hunk_idx , a_hunk_side) , (b_token_idx , b_hunk_idx , b_hunk_side)) in iterate_hunks_rev (a_hunks) . zip (iterate_hunks_rev (b_hunks)) { let a_line = line_content (a_token_idx , a_hunk_side) . as_bstr () ; let b_line = line_content (b_token_idx , b_hunk_side) . as_bstr () ; if last_a_hunk_idx != a_hunk_idx { a_hunk_token_equal_from = None ; last_a_hunk_idx = a_hunk_idx ; } if last_b_hunk_idx != b_hunk_idx { b_hunk_token_equal_from = None ; last_b_hunk_idx = b_hunk_idx ; } if a_line == b_line { (remove_trailing_a_hunks_from , remove_trailing_b_hunks_from) = (Some (a_hunk_idx) , Some (b_hunk_idx)) ; (a_hunk_token_equal_from , b_hunk_token_equal_from) = (Some (a_token_idx) , Some (b_token_idx)) ; } else { break ; } } truncate_hunks_from_from_back (a_hunks , remove_trailing_a_hunks_from , a_hunk_token_equal_from , Some (& mut out) ,) ; truncate_hunks_from_from_back (b_hunks , remove_trailing_b_hunks_from , b_hunk_token_equal_from , None) ; } (out , hunks_in_front) }
    };
}

zealously_contract_hunks!();